#!/data/data/com.termux/files/usr/bin/bash
set -e

echo "Syncing repo..."
git pull --rebase origin main

echo "Removing old adaptive icon files..."
rm -rf app/src/main/res/mipmap-anydpi-v26
rm -f app/src/main/res/drawable/ic_launcher_background.xml app/src/main/res/drawable/ic_launcher_foreground.xml

mkdir -p "app/src/main/java/com/frostbyte/launcher/ui/space"
echo "Writing app/src/main/java/com/frostbyte/launcher/ui/space/SpaceRenderer.kt..."
cat > app/src/main/java/com/frostbyte/launcher/ui/space/SpaceRenderer.kt << 'FILE_EOF'
package com.frostbyte.launcher.ui.space

import androidx.compose.foundation.Image
import androidx.compose.foundation.layout.Box
import androidx.compose.foundation.layout.fillMaxSize
import androidx.compose.runtime.Composable
import androidx.compose.ui.Modifier
import androidx.compose.ui.layout.ContentScale
import androidx.compose.ui.res.painterResource
import com.frostbyte.launcher.R

/**
 * SpaceRenderer - Section 4 of the PRD.
 *
 * Draws the static cosmic black-hole background artwork (res/drawable/bg_space_blackhole).
 * Previously this composed four animated layers (StarField, Nebula, BlackHole,
 * CosmicParticles); that was replaced with a single static image per an
 * explicit product decision to trade the animation for a fixed piece of art,
 * lower battery/CPU cost, and a smaller amount of moving-parts code to
 * maintain. The quality/reducedMotion signature is kept as-is so screens and
 * the Settings screen's space-quality picker don't need to change - a static
 * image just doesn't need to read them to decide anything.
 */
@Composable
fun SpaceRenderer(modifier: Modifier = Modifier) {
    Box(modifier = modifier.fillMaxSize()) {
        Image(
            painter = painterResource(id = R.drawable.bg_space_blackhole),
            contentDescription = null,
            modifier = Modifier.fillMaxSize(),
            contentScale = ContentScale.Crop
        )
    }
}

FILE_EOF

mkdir -p "app/src/main/java/com/frostbyte/launcher/ui/screens/settings"
echo "Writing app/src/main/java/com/frostbyte/launcher/ui/screens/settings/SettingsScreen.kt..."
cat > app/src/main/java/com/frostbyte/launcher/ui/screens/settings/SettingsScreen.kt << 'FILE_EOF'
package com.frostbyte.launcher.ui.screens.settings

import androidx.compose.foundation.layout.Arrangement
import androidx.compose.foundation.layout.Box
import androidx.compose.foundation.layout.Column
import androidx.compose.foundation.layout.PaddingValues
import androidx.compose.foundation.layout.Row
import androidx.compose.foundation.layout.fillMaxSize
import androidx.compose.foundation.layout.fillMaxWidth
import androidx.compose.foundation.lazy.LazyColumn
import androidx.compose.material3.MaterialTheme
import androidx.compose.material3.Switch
import androidx.compose.material3.SwitchDefaults
import androidx.compose.material3.Text
import androidx.compose.runtime.Composable
import androidx.compose.runtime.getValue
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.unit.dp
import androidx.lifecycle.compose.collectAsStateWithLifecycle
import com.frostbyte.launcher.ui.common.frostByteViewModel
import com.frostbyte.launcher.ui.components.GlassCard
import com.frostbyte.launcher.ui.space.SpaceRenderer
import com.frostbyte.launcher.ui.theme.IceBlue
import com.frostbyte.launcher.ui.theme.TextSecondary

@Composable
fun SettingsScreen(
    viewModel: SettingsViewModel = frostByteViewModel { container ->
        SettingsViewModel(container.settingsRepository, container.deviceCapabilitiesProvider)
    }
) {
    val uiState by viewModel.uiState.collectAsStateWithLifecycle()
    val settings = uiState.appSettings

    Box(modifier = Modifier.fillMaxSize()) {
        SpaceRenderer(modifier = Modifier.fillMaxSize())

        LazyColumn(
            modifier = Modifier.fillMaxSize(),
            contentPadding = PaddingValues(20.dp),
            verticalArrangement = Arrangement.spacedBy(16.dp)
        ) {
            item {
                Text(
                    text = "Settings",
                    style = MaterialTheme.typography.displayLarge,
                    color = MaterialTheme.colorScheme.onBackground
                )
            }

            item {
                SettingsSection(title = "Privacy") {
                    Column(verticalArrangement = Arrangement.spacedBy(16.dp)) {
                        ToggleRow(
                            title = "Anonymous usage telemetry",
                            subtitle = "Off by default. Helps improve the launcher.",
                            checked = settings.telemetryEnabled,
                            onCheckedChange = viewModel::setTelemetryEnabled
                        )
                        ToggleRow(
                            title = "Crash reports",
                            subtitle = "Off by default. Never includes passwords or tokens.",
                            checked = settings.crashReportsEnabled,
                            onCheckedChange = viewModel::setCrashReportsEnabled
                        )
                    }
                }
            }
        }
    }
}

@Composable
private fun SettingsSection(title: String, content: @Composable () -> Unit) {
    Column {
        Text(
            text = title.uppercase(),
            style = MaterialTheme.typography.labelSmall,
            color = TextSecondary,
            modifier = Modifier.padding(bottom = 8.dp, start = 4.dp)
        )
        GlassCard(modifier = Modifier.fillMaxWidth()) {
            content()
        }
    }
}

@Composable
private fun ToggleRow(
    title: String,
    subtitle: String,
    checked: Boolean,
    onCheckedChange: (Boolean) -> Unit
) {
    Row(
        modifier = Modifier.fillMaxWidth(),
        horizontalArrangement = Arrangement.SpaceBetween,
        verticalAlignment = Alignment.CenterVertically
    ) {
        Column(modifier = Modifier.weight(1f)) {
            Text(title, style = MaterialTheme.typography.titleMedium, color = MaterialTheme.colorScheme.onSurface)
            Text(subtitle, style = MaterialTheme.typography.bodyMedium, color = TextSecondary)
        }
        Switch(
            checked = checked,
            onCheckedChange = onCheckedChange,
            colors = SwitchDefaults.colors(
                checkedThumbColor = Color(0xFF04040C),
                checkedTrackColor = IceBlue
            )
        )
    }
}

FILE_EOF

